//【童心】
<voice name='童心' class='童心' src='voice/ma03/0012900a09'>
//「……ふむぅ？」
"Hmm?"

//【雷蝶】
<voice name='雷蝶' class='雷蝶' src='voice/ma03/0012910a08'>
